     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	import org.slf4j.Logger;
     6	import org.slf4j.LoggerFactory;
     7	
     8	import java.sql.Connection;
     9	import java.sql.SQLException;
    10	
    11	public class Database {
    12	    private static final Logger logger = LoggerFactory.getLogger(Database.class);
    13	    private static HikariDataSource dataSource;
    14	
    15	    public static void initialize() {
    16	        String dbUrl = System.getenv("DB_URL");
    17	        String dbUser = System.getenv("DB_USER");
    18	        String dbPassword = System.getenv("DB_PASSWORD");
    19	
    20	        if (dbUrl == null || dbUser == null || dbPassword == null) {
    21	            throw new RuntimeException("Database configuration not found in environment variables");
    22	        }
    23	
    24	        HikariConfig config = new HikariConfig();
    25	        config.setJdbcUrl(dbUrl);
    26	        config.setUsername(dbUser);
    27	        config.setPassword(dbPassword);
    28	        config.setMaximumPoolSize(10);
    29	
    30	        dataSource = new HikariDataSource(config);
    31	
    32	        try {
    33	            createTables();
    34	            createRooms();
    35	            logger.info("Database initialized successfully");
    36	        } catch (SQLException e) {
    37	            logger.error("Failed to initialize database", e);
    38	            throw new RuntimeException("Database initialization failed", e);
    39	        }
    40	    }
    41	
    42	    private static void createTables() throws SQLException {
    43	        try (Connection conn = dataSource.getConnection()) {
    44	            conn.createStatement().execute("""
    45	                CREATE TABLE IF NOT EXISTS rooms (
    46	                    number INTEGER PRIMARY KEY,
    47	                    type VARCHAR(50) NOT NULL,
    48	                    capacity INTEGER NOT NULL,
    49	                    nightly_rate NUMERIC(10,2) NOT NULL
    50	                )
    51	                """);
    52	
    53	            conn.createStatement().execute("""
    54	                CREATE TABLE IF NOT EXISTS reservations (
    55	                    id BIGSERIAL PRIMARY KEY,
    56	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
    57	                    guest_name VARCHAR(255) NOT NULL,
    58	                    guest_email VARCHAR(255) NOT NULL,
    59	                    guest_cpf VARCHAR(14),
    60	                    company_cnpj VARCHAR(18),
    61	                    company_name VARCHAR(255),
    62	                    guest_passport VARCHAR(50),
    63	                    guest_country VARCHAR(255),
    64	                    check_in DATE NOT NULL,
    65	                    check_out DATE NOT NULL,
    66	                    guests INTEGER NOT NULL,
    67	                    rate_plan VARCHAR(50) NOT NULL,
    68	                    nights BIGINT NOT NULL,
    69	                    subtotal NUMERIC(10,2) NOT NULL,
    70	                    discount NUMERIC(10,2) NOT NULL,
    71	                    total NUMERIC(10,2) NOT NULL,
    72	                    status VARCHAR(50) NOT NULL,
    73	                    amount_paid NUMERIC(10,2) NOT NULL DEFAULT 0,
    74	                    refund NUMERIC(10,2)
    75	                )
    76	                """);
    77	
    78	            conn.createStatement().execute("""
    79	                CREATE TABLE IF NOT EXISTS messages (
    80	                    id BIGSERIAL PRIMARY KEY,
    81	                    channel VARCHAR(50) NOT NULL,
    82	                    "to" VARCHAR(255) NOT NULL,
    83	                    subject VARCHAR(255) NOT NULL,
    84	                    body TEXT NOT NULL
    85	                )
    86	                """);
    87	
    88	            conn.createStatement().execute("""
    89	                CREATE INDEX IF NOT EXISTS idx_reservation_room_dates
    90	                ON reservations(room_number, check_in, check_out)
    91	                WHERE status != 'CANCELLED'
    92	                """);
    93	        }
    94	    }
    95	
    96	    private static void createRooms() throws SQLException {
    97	        try (Connection conn = dataSource.getConnection();
    98	             var stmt = conn.createStatement()) {
    99	
   100	            // Check if rooms already exist
   101	            var rs = stmt.executeQuery("SELECT COUNT(*) FROM rooms");
   102	            rs.next();
   103	            if (rs.getInt(1) > 0) {
   104	                return;
   105	            }
   106	
   107	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (101, 'STANDARD', 2, 249.90)");
   108	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (102, 'STANDARD', 2, 249.90)");
   109	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (201, 'DELUXE', 3, 389.90)");
   110	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (202, 'DELUXE', 3, 389.90)");
   111	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (301, 'SUITE', 4, 579.90)");
   112	        }
   113	    }
   114	
   115	    public static HikariDataSource getDataSource() {
   116	        return dataSource;
   117	    }
   118	
   119	    public static Connection getConnection() throws SQLException {
   120	        return dataSource.getConnection();
   121	    }
   122	}
