     1	package com.pousada.marealta.handlers;
     2	
     3	import com.pousada.marealta.repository.ReservationRepository;
     4	import com.pousada.marealta.repository.RoomRepository;
     5	import io.javalin.Javalin;
     6	import org.slf4j.Logger;
     7	import org.slf4j.LoggerFactory;
     8	
     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	import java.time.YearMonth;
    12	import java.time.format.DateTimeFormatter;
    13	
    14	public class ReportHandler {
    15	    private static final Logger logger = LoggerFactory.getLogger(ReportHandler.class);
    16	
    17	    public static void register(Javalin app) {
    18	        app.get("/reports/occupancy", ctx -> {
    19	            try {
    20	                String dateStr = ctx.queryParam("date");
    21	                if (dateStr == null) {
    22	                    ctx.status(400);
    23	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
    24	                    return;
    25	                }
    26	
    27	                DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    28	                LocalDate date = LocalDate.parse(dateStr, formatter);
    29	
    30	                StringBuilder csv = new StringBuilder();
    31	                csv.append("room,type,reservation,check_in,check_out\n");
    32	
    33	                int occupiedRooms = 0;
    34	                var rooms = RoomRepository.findAll();
    35	
    36	                for (var room : rooms) {
    37	                    var reservations = ReservationRepository.findByRoomAndDate(room.number(), date);
    38	                    if (!reservations.isEmpty()) {
    39	                        occupiedRooms++;
    40	                        for (var res : reservations) {
    41	                            csv.append(String.format("%d,%s,%d,%s,%s\n",
    42	                                res.getRoomNumber(),
    43	                                room.type(),
    44	                                res.getId(),
    45	                                res.getCheckIn().format(formatter),
    46	                                res.getCheckOut().format(formatter)
    47	                            ));
    48	                        }
    49	                    }
    50	                }
    51	
    52	                csv.append(String.format("total,%d/%d", occupiedRooms, rooms.size()));
    53	
    54	                ctx.contentType("text/csv; charset=utf-8");
    55	                ctx.result(csv.toString());
    56	            } catch (Exception e) {
    57	                logger.error("Error generating occupancy report", e);
    58	                ctx.status(400);
    59	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    60	            }
    61	        });
    62	
    63	        app.get("/reports/revenue", ctx -> {
    64	            try {
    65	                String monthStr = ctx.queryParam("month");
    66	                if (monthStr == null) {
    67	                    ctx.status(400);
    68	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
    69	                    return;
    70	                }
    71	
    72	                YearMonth month = YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
    73	                var reservations = ReservationRepository.findByMonth(month.getYear(), month.getMonthValue());
    74	
    75	                StringBuilder csv = new StringBuilder();
    76	                csv.append("reservation,room,check_in,check_out,status,amount\n");
    77	
    78	                BigDecimal total = BigDecimal.ZERO;
    79	                DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    80	
    81	                for (var res : reservations) {
    82	                    BigDecimal amount = res.getAmountPaid();
    83	                    if (res.getRefund() != null) {
    84	                        amount = amount.subtract(res.getRefund());
    85	                    }
    86	
    87	                    csv.append(String.format("%d,%d,%s,%s,%s,%s\n",
    88	                        res.getId(),
    89	                        res.getRoomNumber(),
    90	                        res.getCheckIn().format(dateFormatter),
    91	                        res.getCheckOut().format(dateFormatter),
    92	                        res.getStatus(),
    93	                        formatBigDecimal(amount)
    94	                    ));
    95	
    96	                    total = total.add(amount);
    97	                }
    98	
    99	                csv.append(String.format("total,,,,%s", formatBigDecimal(total)));
   100	
   101	                ctx.contentType("text/csv; charset=utf-8");
   102	                ctx.result(csv.toString());
   103	            } catch (Exception e) {
   104	                logger.error("Error generating revenue report", e);
   105	                ctx.status(400);
   106	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
   107	            }
   108	        });
   109	    }
   110	
   111	    private static String formatBigDecimal(BigDecimal value) {
   112	        return String.format("%.2f", value);
   113	    }
   114	
   115	    record ErrorResponse(String error, String message) {}
   116	}
