    16	public class ReservationHandler {
    17	    private static final Logger logger = LoggerFactory.getLogger(ReservationHandler.class);
    18	
    19	    public static void register(Javalin app) {
    20	        app.post("/reservations", ctx -> {
    21	            try {
    22	                var req = ctx.bodyAsClass(CreateReservationRequest.class);
    23	                var res = ReservationService.createReservation(req);
    24	                ctx.status(201);
    25	                ctx.json(toResponse(res));
    26	            } catch (ReservationService.ValidationError e) {
    27	                int status = switch (e.code) {
    28	                    case "ROOM_NOT_FOUND" -> 404;
    29	                    case "CAPACITY_EXCEEDED" -> 422;
    30	                    case "ROOM_UNAVAILABLE" -> 409;
    31	                    default -> 400;
    32	                };
    33	                ctx.status(status);
    34	                ctx.json(new ErrorResponse(e.code, e.getMessage()));
    35	            } catch (Exception e) {
    36	                logger.error("Error creating reservation", e);
    37	                ctx.status(500);
    38	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
    39	            }
    40	        });
    41	
    42	        app.get("/reservations/{id}", ctx -> {
    43	            try {
    44	                long id = ctx.pathParamAsClass("id", Long.class).get();
    45	                var res = ReservationRepository.findById(id)
    46	                    .orElseThrow(() -> new ReservationService.ValidationError("RESERVATION_NOT_FOUND", "Reservation not found"));
    47	                ctx.json(toResponse(res));
    48	            } catch (ReservationService.ValidationError e) {
    49	                ctx.status(404);
    50	                ctx.json(new ErrorResponse(e.code, e.getMessage()));
    51	            } catch (Exception e) {
    52	                logger.error("Error fetching reservation", e);
    53	                ctx.status(500);
    54	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
    55	            }
    56	        });
    57	
    58	        app.post("/reservations/{id}/confirmation", ctx -> {
    59	            try {
    60	                long id = ctx.pathParamAsClass("id", Long.class).get();
    61	
    62	                // Parse amount paid from body
    63	                var body = ctx.body();
    64	                var mapper = new com.fasterxml.jackson.databind.ObjectMapper();
    65	                var jsonNode = mapper.readTree(body);
    66	                var amountPaid = new java.math.BigDecimal(jsonNode.get("amountPaid").asText());
    67	
    68	                var res = ReservationService.confirm(id, amountPaid);
    69	
    70	                // Send confirmation email
    71	                try {
    72	                    MessageService.sendConfirmationEmail(res);
    73	                } catch (Exception e) {
    74	                    logger.error("Error sending confirmation email", e);
    75	                }
    76	
    77	                ctx.json(toResponse(res));
    78	            } catch (ReservationService.ValidationError e) {
    79	                int status = e.code.equals("RESERVATION_NOT_FOUND") ? 404 : 409;
    80	                ctx.status(status);
    81	                ctx.json(new ErrorResponse(e.code, e.getMessage()));
    82	            } catch (Exception e) {
    83	                logger.error("Error confirming reservation", e);
    84	                ctx.status(400);
    85	                ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    86	            }
    87	        });
    88	
    89	        app.post("/reservations/{id}/check-in", ctx -> {
    90	            try {
    91	                long id = ctx.pathParamAsClass("id", Long.class).get();
    92	                var res = ReservationService.checkIn(id);
    93	                ctx.json(toResponse(res));
    94	            } catch (ReservationService.ValidationError e) {
    95	                int status = e.code.equals("RESERVATION_NOT_FOUND") ? 404 : 409;
    96	                ctx.status(status);
    97	                ctx.json(new ErrorResponse(e.code, e.getMessage()));
    98	            } catch (Exception e) {
    99	                logger.error("Error checking in reservation", e);
   100	                ctx.status(500);
   101	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
   102	            }
   103	        });
   104	
   105	        app.post("/reservations/{id}/check-out", ctx -> {
   106	            try {
   107	                long id = ctx.pathParamAsClass("id", Long.class).get();
   108	                var res = ReservationService.checkOut(id);
   109	                var room = RoomRepository.findById(res.getRoomNumber()).orElseThrow();
   110	                ctx.json(getDocumentResponse(res, room.type()));
   111	            } catch (ReservationService.ValidationError e) {
   112	                int status = e.code.equals("RESERVATION_NOT_FOUND") ? 404 : 409;
   113	                ctx.status(status);
   114	                ctx.json(new ErrorResponse(e.code, e.getMessage()));
   115	            } catch (Exception e) {
   116	                logger.error("Error checking out reservation", e);
   117	                ctx.status(500);
   118	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
   119	            }
   120	        });
   121	
   122	        app.post("/reservations/{id}/cancellation", ctx -> {
   123	            try {
   124	                long id = ctx.pathParamAsClass("id", Long.class).get();
   125	                var res = ReservationService.cancel(id);
   126	                ctx.json(toResponse(res));
   127	            } catch (ReservationService.ValidationError e) {
   128	                int status = e.code.equals("RESERVATION_NOT_FOUND") ? 404 : 409;
   129	                ctx.status(status);
   130	                ctx.json(new ErrorResponse(e.code, e.getMessage()));
   131	            } catch (Exception e) {
   132	                logger.error("Error cancelling reservation", e);
   133	                ctx.status(500);
   134	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
   135	            }
   136	        });
   137	
   138	        app.get("/reservations/{id}/document", ctx -> {
   139	            try {
   140	                long id = ctx.pathParamAsClass("id", Long.class).get();
   141	                var res = ReservationRepository.findById(id)
   142	                    .orElseThrow(() -> new ReservationService.ValidationError("RESERVATION_NOT_FOUND", "Reservation not found"));
   143	
   144	                if (res.getAmountPaid().signum() == 0) {
   145	                    ctx.status(409);
   146	                    ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document only available for paid reservations"));
   147	                    return;
   148	                }
   149	
   150	                var room = RoomRepository.findById(res.getRoomNumber()).orElseThrow();
   151	                ctx.json(getDocumentResponse(res, room.type()));
   152	            } catch (ReservationService.ValidationError e) {
   153	                int status = e.code.equals("RESERVATION_NOT_FOUND") ? 404 : 409;
   154	                ctx.status(status);
   155	                ctx.json(new ErrorResponse(e.code, e.getMessage()));
   156	            } catch (Exception e) {
   157	                logger.error("Error fetching document", e);
   158	                ctx.status(500);
   159	                ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
   160	            }
   161	        });
   162	    }
   163	
   164	    private static ReservationResponse toResponse(Reservation res) {
   165	        var resp = new ReservationResponse();
   166	        resp.id = res.getId();
   167	        resp.roomNumber = res.getRoomNumber();
   168	        resp.guestName = res.getGuestName();
   169	        resp.guestEmail = res.getGuestEmail();
   170	        resp.guestCpf = res.getGuestCpf();
   171	        resp.companyCnpj = res.getCompanyCnpj();
   172	        resp.companyName = res.getCompanyName();
   173	        resp.guestPassport = res.getGuestPassport();
   174	        resp.guestCountry = res.getGuestCountry();
   175	        resp.checkIn = DocumentFormatter.formatDateISO(res.getCheckIn());
   176	        resp.checkOut = DocumentFormatter.formatDateISO(res.getCheckOut());
   177	        resp.guests = res.getGuests();
   178	        resp.ratePlan = res.getRatePlan().toString();
   179	        resp.nights = res.getNights();
   180	        resp.subtotal = res.getSubtotal();
   181	        resp.discount = res.getDiscount();
   182	        resp.total = res.getTotal();
   183	        resp.status = res.getStatus().toString();
   184	        resp.amountPaid = res.getAmountPaid();
   185	        resp.refund = res.getRefund();
   186	        return resp;
   187	    }
   188	
   189	    private static DocumentResponse getDocumentResponse(Reservation res, String roomType) {
   190	        var doc = new DocumentResponse();
   191	        doc.reservationId = res.getId();
   192	        doc.guestName = res.getGuestName();
   193	        doc.guestCpf = res.getGuestCpf();
   194	        doc.companyCnpj = res.getCompanyCnpj();
   195	        doc.companyName = res.getCompanyName();
   196	        doc.guestPassport = res.getGuestPassport();
   197	        doc.guestCountry = res.getGuestCountry();
   198	        doc.roomNumber = res.getRoomNumber();
   199	        doc.roomType = roomType;
   200	        doc.checkIn = DocumentFormatter.formatDateISO(res.getCheckIn());
   201	        doc.checkOut = DocumentFormatter.formatDateISO(res.getCheckOut());
   202	        doc.nights = res.getNights();
   203	        doc.subtotal = res.getSubtotal();
   204	        doc.discount = res.getDiscount();
   205	        doc.total = res.getTotal();
   206	
   207	        if (res.getGuestCpf() != null) {
   208	            doc.title = "Comprovante de reserva";
   209	            doc.text = DocumentFormatter.formatComprovante(res, roomType);
   210	        } else if (res.getCompanyCnpj() != null) {
   211	            doc.title = "Fatura de hospedagem";
   212	            doc.text = DocumentFormatter.formatFatura(res, roomType);
   213	            doc.iss = res.getTotal().multiply(new java.math.BigDecimal("0.05"))
   214	                .setScale(2, java.math.RoundingMode.HALF_EVEN);
   215	        } else if (res.getGuestPassport() != null) {
   216	            doc.title = "Booking receipt";
   217	            doc.text = DocumentFormatter.formatBookingReceipt(res, roomType);
   218	        }
   219	
   220	        return doc;
   221	    }
   222	
   223	    record ErrorResponse(String error, String message) {}
   224	}
