   163	        if (req.guestCpf != null) identCount++;
   164	        if (req.companyCnpj != null) identCount++;
   165	        if (req.guestPassport != null) identCount++;
   166	
   167	        if (identCount == 0) {
   168	            throw new ValidationError("INVALID_REQUEST", "Identification is required");
   169	        }
   170	
