     1	package com.pousada.marealta.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class PriceCalculator {
     8	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
     9	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    10	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
    11	    private static final int SCALE = 2;
    12	
    13	    public static boolean isHighSeason(LocalDate date) {
    14	        int month = date.getMonthValue();
    15	        int day = date.getDayOfMonth();
    16	
    17	        // July (month 7)
    18	        if (month == 7) {
    19	            return true;
    20	        }
    21	
    22	        // December 15 to February 28 (months 12, 1, 2)
    23	        if (month == 12 && day >= 15) {
    24	            return true;
    25	        }
    26	        if (month == 1 || month == 2) {
    27	            return true;
    28	        }
    29	
    30	        return false;
    31	    }
    32	
    33	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
    34	        BigDecimal price = baseRate;
    35	        if (isHighSeason(date)) {
    36	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
    37	        }
    38	        return price.setScale(SCALE, ROUNDING_MODE);
    39	    }
    40	
    41	    public static long calculateNights(LocalDate checkIn, LocalDate checkOut) {
    42	        return checkOut.toEpochDay() - checkIn.toEpochDay();
    43	    }
    44	
    45	    public static PriceBreakdown calculatePrice(BigDecimal baseRate, LocalDate checkIn,
    46	                                                LocalDate checkOut, String ratePlan) {
    47	        long nights = calculateNights(checkIn, checkOut);
    48	
    49	        BigDecimal subtotal = BigDecimal.ZERO;
    50	        LocalDate currentDate = checkIn;
    51	        for (int i = 0; i < nights; i++) {
    52	            subtotal = subtotal.add(calculateNightlyPrice(baseRate, currentDate));
    53	            currentDate = currentDate.plusDays(1);
    54	        }
    55	        subtotal = subtotal.setScale(SCALE, ROUNDING_MODE);
    56	
    57	        BigDecimal discount = BigDecimal.ZERO;
    58	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    59	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE)
    60	                .setScale(SCALE, ROUNDING_MODE);
    61	        }
    62	
    63	        BigDecimal total = subtotal.subtract(discount)
    64	            .setScale(SCALE, ROUNDING_MODE);
    65	
    66	        return new PriceBreakdown(nights, subtotal, discount, total);
    67	    }
    68	
    69	    public record PriceBreakdown(long nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    70	}
