388	     8	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
389	     9	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
390	    10	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
391	    11	    private static final int SCALE = 2;
