393	    13	    public static boolean isHighSeason(LocalDate date) {
394	    14	        int month = date.getMonthValue();
395	    15	        int day = date.getDayOfMonth();
396	    16	
397	    17	        // July (month 7)
398	    18	        if (month == 7) {
399	    19	            return true;
400	    20	        }
401	    21	
402	    22	        // December 15 to February 28 (months 12, 1, 2)
403	    23	        if (month == 12 && day >= 15) {
404	    24	            return true;
405	    25	        }
406	    26	        if (month == 1 || month == 2) {
407	    27	            return true;
408	    28	        }
409	    29	
410	    30	        return false;
411	    31	    }
412	    32	
413	    33	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
414	    34	        BigDecimal price = baseRate;
415	    35	        if (isHighSeason(date)) {
416	    36	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
417	    37	        }
418	    38	        return price.setScale(SCALE, ROUNDING_MODE);
419	    39	    }
420	    40	
421	    41	    public static long calculateNights(LocalDate checkIn, LocalDate checkOut) {
422	    42	        return checkOut.toEpochDay() - checkIn.toEpochDay();
423	    43	    }
