425	    45	    public static PriceBreakdown calculatePrice(BigDecimal baseRate, LocalDate checkIn,
426	    46	                                                LocalDate checkOut, String ratePlan) {
427	    47	        long nights = calculateNights(checkIn, checkOut);
428	    48	
429	    49	        BigDecimal subtotal = BigDecimal.ZERO;
430	    50	        LocalDate currentDate = checkIn;
431	    51	        for (int i = 0; i < nights; i++) {
432	    52	            subtotal = subtotal.add(calculateNightlyPrice(baseRate, currentDate));
433	    53	            currentDate = currentDate.plusDays(1);
434	    54	        }
435	    55	        subtotal = subtotal.setScale(SCALE, ROUNDING_MODE);
436	    56	
437	    57	        BigDecimal discount = BigDecimal.ZERO;
438	    58	        if ("NON_REFUNDABLE".equals(ratePlan)) {
439	    59	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE)
440	    60	                .setScale(SCALE, ROUNDING_MODE);
441	    61	        }
442	    62	
443	    63	        BigDecimal total = subtotal.subtract(discount)
444	    64	            .setScale(SCALE, ROUNDING_MODE);
445	    65	
