    23	            super(message);
    24	            this.code = code;
    25	        }
    26	    }
    27	
    28	    public static Reservation createReservation(CreateReservationRequest req) throws Exception {
    29	        validateRequest(req);
    30	
    31	        int roomNumber = req.roomNumber;
    32	        LocalDate checkIn = parseDate(req.checkIn);
    33	        LocalDate checkOut = parseDate(req.checkOut);
    34	        int guests = req.guests;
    35	        String ratePlanStr = req.ratePlan;
    36	
    37	        // Validate dates
    38	        if (!checkOut.isAfter(checkIn)) {
    39	            throw new ValidationError("INVALID_REQUEST", "Check-out must be after check-in");
    40	        }
    41	
    42	        // Check room exists
    43	        var room = RoomRepository.findById(roomNumber)
    44	            .orElseThrow(() -> new ValidationError("ROOM_NOT_FOUND", "Room not found"));
    45	
    46	        // Check capacity
    47	        if (guests > room.capacity()) {
    48	            throw new ValidationError("CAPACITY_EXCEEDED", "Too many guests for this room");
    49	        }
    50	
    51	        if (guests < 1) {
    52	            throw new ValidationError("INVALID_REQUEST", "At least one guest is required");
    53	        }
    54	
    55	        // Check availability
    56	        if (ReservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    57	            throw new ValidationError("ROOM_UNAVAILABLE", "Room is not available for these dates");
    58	        }
    59	
    60	        // Calculate prices
    61	        RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
    62	        var priceBreakdown = PriceCalculator.calculatePrice(room.nightlyRate(), checkIn, checkOut, ratePlanStr);
    63	
    64	        // Create reservation
    65	        Reservation res = new Reservation();
    66	        res.setRoomNumber(roomNumber);
    67	        res.setGuestName(req.guestName);
    68	        res.setGuestEmail(req.guestEmail);
    69	        res.setGuestCpf(req.guestCpf);
